python3 << 'EOF'
import json

with open('/app/resources/treasury_bulletin_1992_03.json') as f:
    data = json.load(f)

# Search for figures (charts) that might be on page 148
for i, elem in enumerate(data['document']['elements']):
    if elem.get('type') == 'figure':
        content = elem.get('content', '')
        if content:
            print(f"Element {i}: content={str(content)[:200]}")
        else:
            print(f"Element {i}: figure with no content")
EOF
